    if not path.is_file():
        raise FixtureError("FIXTURE_NOT_AVAILABLE", "The fixture scenario file is missing.")
    raw = path.read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected_sha256:
        raise FixtureError("FIXTURE_CHECKSUM_INVALID", "The fixture checksum does not match the manifest.")
    try:
        payload = json.loads(raw)
    except json.JSONDecodeError:
        raise FixtureError("FIXTURE_SCHEMA_INVALID", "The fixture scenario is not valid JSON.") from None
    if not isinstance(payload, dict):
